-- Data for table: reviews (55 records)
INSERT INTO reviews (id, user_id, event_id, rating, comment, created_at, updated_at) VALUES
  (1, 14, 1, 5, 'Absolutely breathtaking sound design and stage presence! Will definitely attend next year.', '2026-06-16T19:30:00+05:30', '2026-06-16T19:30:00+05:30'),
  (2, 15, 2, 5, 'Incredible insights from the speakers. Seamless badge collection and great networking tracks.', '2026-06-28T19:30:00+05:30', '2026-06-28T19:30:00+05:30'),
  (3, 16, 3, 4, 'Great lineup and well organized. The venue was easy to access, though lines were long.', '2026-07-12T19:30:00+05:30', '2026-07-12T19:30:00+05:30'),
  (4, 17, 4, 4, 'Hilarious performances throughout! Highly recommend Catching this live.', '2026-07-27T19:30:00+05:30', '2026-07-27T19:30:00+05:30'),
  (5, 18, 5, 5, 'Hands-on, highly practical content that I immediately applied to my job.', '2026-08-08T19:30:00+05:30', '2026-08-08T19:30:00+05:30'),
  (6, 19, 6, 3, 'Good content overall, but the auditorium acoustics had noticeable echo in back rows.', '2026-08-20T19:30:00+05:30', '2026-08-20T19:30:00+05:30'),
  (7, 20, 7, 4, 'Very high energy and smooth game casting. Super fun community tournament.', '2026-08-31T19:30:00+05:30', '2026-08-31T19:30:00+05:30'),
  (8, 41, 1, 5, 'Wonderful evening and high quality connections made with fellow founders.', '2026-06-14T19:30:00+05:30', '2026-06-14T19:30:00+05:30'),
  (9, 42, 2, 2, 'Content was decent but the parking management at the venue was quite chaotic.', '2026-06-30T19:30:00+05:30', '2026-06-30T19:30:00+05:30'),
  (10, 43, 3, 4, 'Splendid organization and prompt schedule adherence. Well done to the team!', '2026-07-11T19:30:00+05:30', '2026-07-11T19:30:00+05:30'),
  (11, 44, 4, 5, 'Phenomenal musical experience! The light show during the finale was top notch.', '2026-07-25T19:30:00+05:30', '2026-07-25T19:30:00+05:30'),
  (12, 45, 5, 4, 'Thought-provoking panel discussions. Appreciate the clear timekeeping.', '2026-08-08T19:30:00+05:30', '2026-08-08T19:30:00+05:30'),
  (13, 14, 6, 5, 'Absolutely breathtaking sound design and stage presence! Will definitely attend next year.', '2026-08-23T19:30:00+05:30', '2026-08-23T19:30:00+05:30'),
